import{_ as o,C as r,c as i,o as t,a2 as a,b as d,w as s,a as u,G as c,a3 as l}from"./chunks/framework.DkPtUiZm.js";const C=JSON.parse('{"title":"Où vit la documentation","description":"","frontmatter":{},"headers":[],"relativePath":"fondations/ou-vit-la-documentation.md","filePath":"fondations/ou-vit-la-documentation.md","lastUpdated":1790233006000}'),p={name:"fondations/ou-vit-la-documentation.md"};function m(h,e,q,g,b,f){const n=r("Mermaid");return t(),i("div",null,[e[1]||(e[1]=a('<h1 id="ou-vit-la-documentation" tabindex="-1">Où vit la documentation <a class="header-anchor" href="#ou-vit-la-documentation" aria-label="Permalink to &quot;Où vit la documentation&quot;">​</a></h1><h2 id="le-probleme" tabindex="-1">Le problème <a class="header-anchor" href="#le-probleme" aria-label="Permalink to &quot;Le problème&quot;">​</a></h2><p>La documentation racontait l&#39;histoire de son propre développement. Le sommaire alignait « Sprint 2 », « Vague 1 », « Audit du legacy », « Vague 2 », « Les briques du quotidien » — des titres qui disent quand une chose a été faite, jamais ce qu&#39;elle fait. Quelqu&#39;un qui cherchait comment afficher un tableau devait deviner dans quelle vague il était tombé.</p><p>Rien ne disait non plus <strong>quelles props</strong> prend un composant. Cent trois composants, mille huit props, et pas une page pour les lire : il fallait ouvrir le code, ou cliquer dans Storybook composant par composant.</p><h2 id="quatre-surfaces-quatre-questions" tabindex="-1">Quatre surfaces, quatre questions <a class="header-anchor" href="#quatre-surfaces-quatre-questions" aria-label="Permalink to &quot;Quatre surfaces, quatre questions&quot;">​</a></h2><p>Chacune répond à une question que les autres ne posent pas. C&#39;est la règle qui les sépare, et c&#39;est aussi ce qui empêche une information d&#39;exister à deux endroits.</p>',6)),(t(),d(l,null,{default:s(()=>[c(n,{id:"mermaid-18",class:"mermaid",graph:"flowchart%20TB%0A%20%20subgraph%20Sources%5B%22Ce%20qui%20fait%20foi%22%5D%0A%20%20%20%20Types%5B%22Types%20TypeScript%3Cbr%2F%3E%2B%20commentaires%22%5D%0A%20%20%20%20Reg%5B%22registry.json%22%5D%0A%20%20%20%20Prose%5B%22Markdown%20%C3%A9crit%3Cbr%2F%3E%C3%A0%20la%20main%22%5D%0A%20%20%20%20Stories%5B%22Stories%22%5D%0A%20%20%20%20Demo%5B%22Application%20de%3Cbr%2F%3Ed%C3%A9monstration%22%5D%0A%20%20end%0A%0A%20%20Types%20--%3E%20Ref%5B%22%2Fcomposants%2F%3Cbr%2F%3ER%C3%A9f%C3%A9rence%22%5D%0A%20%20Reg%20--%3E%20Ref%0A%20%20Types%20--%3E%20Cat%5B%22%2Fstorybook%2F%3Cbr%2F%3ECatalogue%22%5D%0A%20%20Stories%20--%3E%20Cat%0A%20%20Prose%20--%3E%20Site%5B%22%2F%3Cbr%2F%3EDocumentation%22%5D%0A%20%20Demo%20--%3E%20Prev%5B%22%2Fpreview%2F%3Cbr%2F%3ED%C3%A9monstration%22%5D%0A%0A%20%20Ref%20-.-%3E%7C%22%C2%AB%20quelles%20props%20%3F%20%C2%BB%22%7C%20Q1%5B%22%20%22%5D%0A%20%20Cat%20-.-%3E%7C%22%C2%AB%20quel%20rendu%20%3F%20%C2%BB%22%7C%20Q2%5B%22%20%22%5D%0A%20%20Site%20-.-%3E%7C%22%C2%AB%20pourquoi%20ainsi%20%3F%20%C2%BB%22%7C%20Q3%5B%22%20%22%5D%0A%20%20Prev%20-.-%3E%7C%22%C2%AB%20en%20situation%20%3F%20%C2%BB%22%7C%20Q4%5B%22%20%22%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[u(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a(`<table tabindex="0"><thead><tr><th>Surface</th><th>Question</th><th>Écrite par</th></tr></thead><tbody><tr><td><a href="/sia-ui-site/composants/">Référence</a></td><td>quelles props, quels types, quels défauts</td><td><code>scripts/generer-reference.mjs</code></td></tr><tr><td><a href="/sia-ui-site/storybook/">Catalogue</a></td><td>à quoi ça ressemble, dans quel état</td><td>les stories</td></tr><tr><td><a href="/sia-ui-site/preview/">Démonstration</a></td><td>à quoi ça ressemble dans un écran entier</td><td>l&#39;application de démonstration</td></tr><tr><td>Ces pages</td><td>pourquoi c&#39;est fait ainsi</td><td>des humains</td></tr></tbody></table><h2 id="la-reference-est-ecrite-par-le-code" tabindex="-1">La référence est écrite par le code <a class="header-anchor" href="#la-reference-est-ecrite-par-le-code" aria-label="Permalink to &quot;La référence est écrite par le code&quot;">​</a></h2><p>Les props d&#39;un composant sont déjà décrites une fois : dans ses types et leurs commentaires. Les recopier dans du Markdown en ferait une seconde description, qui divergerait à la première prop ajoutée — sans que rien ne le signale, puisque rien ne relie les deux.</p><p><code>scripts/generer-reference.mjs</code> lit donc les types et n&#39;écrit que ce qu&#39;il y trouve :</p><table tabindex="0"><thead><tr><th>Ce qu&#39;on cherche</th><th>D&#39;où ça vient</th></tr></thead><tbody><tr><td>à quoi sert le composant</td><td>le commentaire au-dessus de la fonction</td></tr><tr><td>comment l&#39;utiliser</td><td>le bloc d&#39;exemple de ce commentaire</td></tr><tr><td>ses props, types et défauts</td><td>les types eux-mêmes</td></tr><tr><td>comment l&#39;installer</td><td><code>packages/registry/registry.json</code></td></tr></tbody></table><p>L&#39;extracteur est celui de Storybook — <code>react-docgen-typescript</code>. Les deux surfaces montrent donc les mêmes tableaux, sans qu&#39;aucune ne recopie l&#39;autre.</p><p>Les pages produites ne sont <strong>pas</strong> suivies par Git (<code>docs/.gitignore</code>) : ce serait le même contenu, stocké deux fois.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:reference</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 24 s, 103 pages</span></span></code></pre></div><p>La construction du site les régénère toujours. Le serveur de développement les laisse en place si elles existent — vingt-quatre secondes à chaque démarrage pour des pages inchangées seraient vingt-quatre secondes de trop.</p><h3 id="une-page-vaut-ce-que-vaut-son-commentaire" tabindex="-1">Une page vaut ce que vaut son commentaire <a class="header-anchor" href="#une-page-vaut-ce-que-vaut-son-commentaire" aria-label="Permalink to &quot;Une page vaut ce que vaut son commentaire&quot;">​</a></h3><p>Un composant sans commentaire donnerait une page sans explication, qui retomberait sur la description anglaise du registre. Ce ne serait pas un défaut du générateur : c&#39;est le commentaire qui manquerait, et il manquerait aussi dans l&#39;éditeur de quiconque utilise le composant.</p><p><strong>Les cent trois composants en ont un.</strong> Ce que chacun doit dire n&#39;est pas ce que la signature répète déjà — « un bouton avec un libellé et un <code>onClick</code> » n&#39;apprend rien — mais ce qui ne se lit pas dans le code : ce que le composant résout, et pourquoi il le résout ainsi.</p><p>Un module sans composant principal fait exception : <code>Icons</code> est une collection, et sa description ne peut être accrochée à aucune des douze fonctions qu&#39;il exporte. Elle vit alors <strong>en tête de fichier</strong>, avant les imports — le seul endroit qui parle du module entier, et que le générateur lit à défaut.</p><p><code>pnpm check:descriptions</code> refuse un composant sans commentaire, et la CI le lance. Il ne juge pas ce que le commentaire contient — aucun outil ne sait faire la différence entre une phrase utile et une paraphrase de la signature.</p><h2 id="le-catalogue-a-neuf-sections" tabindex="-1">Le catalogue a neuf sections <a class="header-anchor" href="#le-catalogue-a-neuf-sections" aria-label="Permalink to &quot;Le catalogue a neuf sections&quot;">​</a></h2><p>Elles étaient seize, en deux langues, avec des doublons : <code>Foundations</code> et <code>Fondations</code> côte à côte, <code>Data</code> séparant <code>Chart</code> des autres données. Personne ne l&#39;avait décidé — chaque story avait été écrite en recopiant la précédente, ou pas. Faute d&#39;ordre déclaré, Storybook les triait alphabétiquement.</p><p>L&#39;ordre va du plus général au plus assemblé :</p><table tabindex="0"><thead><tr><th>Section</th><th>Ce qu&#39;on y trouve</th></tr></thead><tbody><tr><td>Fondations</td><td>ce qui règle le thème, la locale, le positionnement</td></tr><tr><td>Primitives</td><td>ce qui se pose seul — <code>Button</code>, <code>Badge</code>, <code>Input</code></td></tr><tr><td>Saisie</td><td>tout ce qui prend une valeur</td></tr><tr><td>Dates et heures</td><td>calendriers, sélecteurs, durées</td></tr><tr><td>Données</td><td>ce qui affiche — tableaux, montants, graphiques</td></tr><tr><td>Retour</td><td>ce qui répond — alertes, boîtes, surfaces flottantes</td></tr><tr><td>Navigation</td><td>ce qui mène ailleurs</td></tr><tr><td>Mise en page</td><td>ce qui porte le reste</td></tr><tr><td>Patterns</td><td>ce qui compose tout cela en écran</td></tr></tbody></table><p>L&#39;ordre est déclaré dans <code>apps/docs/.storybook/preview.tsx</code>, et <code>pnpm check:stories</code> refuse une section hors de cette liste, un titre sans composant, ou deux stories sous le même titre. La CI le lance.</p><h2 id="l-arborescence-des-pages-ecrites" tabindex="-1">L&#39;arborescence des pages écrites <a class="header-anchor" href="#l-arborescence-des-pages-ecrites" aria-label="Permalink to &quot;L&#39;arborescence des pages écrites&quot;">​</a></h2><p>Les documents ne portent plus de numéro. Un numéro dit l&#39;ordre d&#39;écriture, c&#39;est-à-dire la seule chose dont un lecteur n&#39;a que faire.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docs/</span></span>
<span class="line"><span>  demarrer/      ce que c&#39;est, comment poser le thème</span></span>
<span class="line"><span>  guides/        comment faire une chose précise</span></span>
<span class="line"><span>  composants/    la référence — produite, non suivie par Git</span></span>
<span class="line"><span>  fondations/    comment c&#39;est construit, et pourquoi</span></span>
<span class="line"><span>  distribution/  registre, CLI, site, validation</span></span>
<span class="line"><span>  decisions/     le détail d&#39;un choix, quand il mérite d&#39;être retrouvé</span></span>
<span class="line"><span>  contribuer/    conventions et outillage</span></span></code></pre></div><p>Le sommaire vit dans <code>docs/README.md</code>, sous « ## Sommaire », groupé par titres de niveau trois. <code>.vitepress/sidebar.ts</code> le lit : il n&#39;y a donc pas deux ordres de lecture qui divergent, celui de GitHub et celui du site. La référence fait exception — elle compte cent trois pages, et les énumérer à la main serait recopier une troisième fois ce que le code sait déjà.</p><h2 id="ce-qui-a-ete-retire" tabindex="-1">Ce qui a été retiré <a class="header-anchor" href="#ce-qui-a-ete-retire" aria-label="Permalink to &quot;Ce qui a été retiré&quot;">​</a></h2><p>Huit comptes rendus de développement : les quatre vagues, le sprint, les deux documents d&#39;audit et de clôture, et le relevé d&#39;une phase. Ils décrivaient un chemin parcouru, pas un produit — et la bibliothèque est neuve : elle n&#39;a pas d&#39;héritage à solder.</p><p>La feuille de route a quitté le site pour <code>ROADMAP.md</code>, à la racine. C&#39;est un document de planification, écrit à la deuxième personne ; il reste lisible sur GitHub, où il a sa place, plutôt que publié comme documentation.</p><h2 id="voir-aussi" tabindex="-1">Voir aussi <a class="header-anchor" href="#voir-aussi" aria-label="Permalink to &quot;Voir aussi&quot;">​</a></h2><ul><li><a href="./../distribution/site-et-catalogue.html">Site, catalogue et démonstration</a> — comment les quatre surfaces sont construites et mises en ligne.</li><li><a href="./source-unique.html">Source unique des composants web</a> — la même règle, appliquée au code.</li></ul>`,28))])}const A=o(p,[["render",m]]);export{C as __pageData,A as default};
